"""Checks that relative links and anchors in Markdown files resolve."""

import re
import sys
from pathlib import Path
from urllib.parse import unquote

from common import REPO_ROOT, list_files, relative

_FENCE = re.compile(r"^\s*(```|~~~)")
_INLINE_CODE = re.compile(r"`[^`]*`")
_LINK = re.compile(r"!?\[[^\]]*\]\(\s*<?([^)\s>]+)>?(?:\s+\"[^\"]*\")?\s*\)")
_REFERENCE = re.compile(r"^\s{0,3}\[[^\]]+\]:\s*<?(\S+?)>?(?:\s+.*)?$")
_HEADING = re.compile(r"^\s{0,3}(#{1,6})\s+(.*?)\s*#*\s*$")
_EXTERNAL = re.compile(r"^([a-zA-Z][a-zA-Z0-9+.-]*:|//)")


def slugify(heading: str) -> str:
    """Returns the GitHub anchor of a heading."""
    text = re.sub(r"\[([^\]]*)\]\([^)]*\)", r"\1", heading)
    text = re.sub(r"[`*_]", "", text).strip().lower()
    text = re.sub(r"[^\w\- ]", "", text)
    return text.replace(" ", "-")


def _body_lines(text: str):
    """Yields (line number, line) outside fenced code blocks."""
    in_fence = False
    for number, line in enumerate(text.splitlines(), start=1):
        if _FENCE.match(line):
            in_fence = not in_fence
            continue
        if not in_fence:
            yield number, line


def anchors_of(text: str) -> set[str]:
    """Returns the anchors generated by the headings of a document."""
    seen: dict[str, int] = {}
    anchors = set()
    for _, line in _body_lines(text):
        match = _HEADING.match(line)
        if not match:
            continue
        slug = slugify(match.group(2))
        count = seen.get(slug, 0)
        seen[slug] = count + 1
        anchors.add(slug if count == 0 else f"{slug}-{count}")
    return anchors


def targets_of(text: str):
    """Yields (line number, link target) for each link of a document."""
    for number, line in _body_lines(text):
        stripped = _INLINE_CODE.sub("", line)
        for match in _LINK.finditer(stripped):
            yield number, match.group(1)
        reference = _REFERENCE.match(stripped)
        if reference:
            yield number, reference.group(1)


def check(root: Path = REPO_ROOT) -> list[str]:
    """Returns one message per broken internal link."""
    errors = []
    for path in list_files(root):
        if path.suffix.lower() != ".md":
            continue
        text = path.read_text(encoding="utf-8-sig", errors="replace")
        for number, target in targets_of(text):
            if _EXTERNAL.match(target):
                continue
            where = f"{relative(path, root)}:{number}"
            file_part, _, anchor = target.partition("#")
            file_part = unquote(file_part)
            if file_part:
                base = root if file_part.startswith("/") else path.parent
                destination = (base / file_part.lstrip("/")).resolve()
                if not destination.exists():
                    errors.append(f"{where}: broken link '{target}'")
                    continue
            else:
                destination = path
            if anchor and destination.suffix.lower() == ".md" and destination.is_file():
                doc = destination.read_text(encoding="utf-8-sig", errors="replace")
                if unquote(anchor).lower() not in anchors_of(doc):
                    errors.append(f"{where}: unknown anchor '#{anchor}' in '{target}'")
    return errors


def main() -> int:
    errors = check()
    for error in errors:
        print(error)
    if errors:
        print(f"{len(errors)} broken link(s).")
        return 1
    print("Internal links: OK")
    return 0


if __name__ == "__main__":
    sys.exit(main())
